-- EDUNEXUS curriculum expansion v2: original instructional content inspired by referenced public frameworks.
-- Safe to re-run. No production data is changed until this migration is applied to production.
BEGIN;

INSERT INTO public.programs (name, slug, description)
VALUES ('Literasi Digital, AI, dan Kesiapan Karier', 'literasi-digital-ai-kesiapan-karier',
        'Keterampilan lintas bidang untuk menilai informasi, menggunakan teknologi secara aman, memahami AI, dan merencanakan pengembangan karier.')
ON CONFLICT (slug) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, updated_at=now();

INSERT INTO public.skills (slug,name,domain,description) VALUES
('literasi-informasi-kritis','Literasi Informasi Kritis','hard_skill','Menemukan, memeriksa, membandingkan, dan mengutip informasi secara bertanggung jawab.'),
('literasi-digital-aman','Literasi Digital dan Keamanan','hard_skill','Menggunakan perangkat dan layanan digital secara aman, inklusif, dan sadar privasi.'),
('literasi-ai-bertanggung-jawab','Literasi AI Bertanggung Jawab','hard_skill','Memahami batasan AI, mengevaluasi keluaran, dan menggunakan AI secara etis.'),
('perencanaan-karier','Perencanaan Karier','soft_skill','Memetakan keterampilan, bukti, kebutuhan belajar, dan langkah karier berikutnya.'),
('berpikir-kritis','Berpikir Kritis','soft_skill','Mengevaluasi klaim, bukti, asumsi, dan alternatif sebelum mengambil keputusan.'),
('pembelajaran-mandiri','Pembelajaran Mandiri','soft_skill','Menetapkan tujuan, memonitor kemajuan, meminta umpan balik, dan merefleksikan hasil.')
ON CONFLICT (slug) DO UPDATE SET name=EXCLUDED.name, domain=EXCLUDED.domain, description=EXCLUDED.description, updated_at=now();

INSERT INTO public.courses (program_id,name,slug,description)
SELECT p.id,v.name,v.slug,v.description FROM public.programs p CROSS JOIN (VALUES
('Literasi Informasi dan Berpikir Kritis','literasi-informasi-berpikir-kritis','Strategi pencarian, evaluasi kredibilitas, penalaran berbasis bukti, dan komunikasi temuan.'),
('Literasi Digital dan Keamanan Data','literasi-digital-keamanan-data','Privasi, keamanan akun, jejak digital, kolaborasi daring, dan aksesibilitas.'),
('Kecerdasan Buatan: Dasar, Etika, dan Praktik','kecerdasan-buatan-dasar-etika-praktik','Dasar AI, evaluasi keluaran, prompting, verifikasi, privasi, dan tanggung jawab manusia.'),
('Perencanaan Karier dan Portofolio Keterampilan','perencanaan-karier-portofolio-keterampilan','Pemetaan kompetensi, bukti kerja, target belajar, dan rencana pengembangan karier.')
) AS v(name,slug,description)
WHERE p.slug='literasi-digital-ai-kesiapan-karier'
ON CONFLICT (slug) DO UPDATE SET program_id=EXCLUDED.program_id,name=EXCLUDED.name,description=EXCLUDED.description,updated_at=now();

INSERT INTO public.modules (course_id,name,position)
SELECT c.id,v.name,v.position FROM public.courses c JOIN (VALUES
('literasi-informasi-berpikir-kritis','Merumuskan dan Menelusuri Pertanyaan',1),
('literasi-informasi-berpikir-kritis','Mengevaluasi Bukti dan Klaim',2),
('literasi-informasi-berpikir-kritis','Menyusun Kesimpulan yang Jujur',3),
('literasi-digital-keamanan-data','Identitas Digital dan Privasi',1),
('literasi-digital-keamanan-data','Keamanan Akun dan Perangkat',2),
('literasi-digital-keamanan-data','Kolaborasi Digital yang Inklusif',3),
('kecerdasan-buatan-dasar-etika-praktik','Memahami Cara Kerja dan Batasan AI',1),
('kecerdasan-buatan-dasar-etika-praktik','Merancang Prompt dan Memverifikasi Jawaban',2),
('kecerdasan-buatan-dasar-etika-praktik','Etika, Privasi, dan Akuntabilitas',3),
('perencanaan-karier-portofolio-keterampilan','Memetakan Keterampilan dan Minat',1),
('perencanaan-karier-portofolio-keterampilan','Bukti Kompetensi dan Portofolio',2),
('perencanaan-karier-portofolio-keterampilan','Rencana Pengembangan 90 Hari',3)
) AS v(course_slug,name,position) ON c.slug=v.course_slug
ON CONFLICT (course_id,position) DO UPDATE SET name=EXCLUDED.name;

INSERT INTO public.lessons (module_id,title,content,position)
SELECT m.id,v.title,jsonb_build_object(
'sources',CASE v.course_slug
 WHEN 'literasi-informasi-berpikir-kritis' THEN jsonb_build_array(
  jsonb_build_object('title','Kurikulum Nasional: CP & ATP','url','https://guru.kemendikdasmen.go.id/kurikulum/referensi-penerapan/capaian-pembelajaran/','note','Rujukan konteks kurikulum Indonesia; materi EDUNEXUS tetap sintesis orisinal.'),
  jsonb_build_object('title','Asesmen Kompetensi Minimum','url','https://pusmendik.kemdikbud.go.id/an/akm?j=2&l=1','note','Referensi literasi membaca dan numerasi.'),
  jsonb_build_object('title','DigComp 2.2','url','https://pact-for-skills.ec.europa.eu/community-resources/publications-and-documents/digcomp-22-digital-competence-framework-citizens_en','note','Kerangka kompetensi digital internasional; dikontekstualisasikan.'))
 WHEN 'literasi-digital-keamanan-data' THEN jsonb_build_array(
  jsonb_build_object('title','DigComp 2.2','url','https://pact-for-skills.ec.europa.eu/community-resources/publications-and-documents/digcomp-22-digital-competence-framework-citizens_en','note','Kerangka kompetensi digital; bukan regulasi Indonesia.'),
  jsonb_build_object('title','Panduan UNESCO tentang GenAI dalam pendidikan','url','https://www.unesco.org/en/articles/guidance-generative-ai-education-and-research','note','Rujukan pendekatan berpusat pada manusia dan perlindungan data.'))
 WHEN 'kecerdasan-buatan-dasar-etika-praktik' THEN jsonb_build_array(
  jsonb_build_object('title','UNESCO AI Competency Framework for Students','url','https://www.unesco.org/en/articles/ai-competency-framework-students','note','Kerangka literasi AI untuk pembelajar; pelajaran ini merupakan adaptasi orisinal.'),
  jsonb_build_object('title','UNESCO AI Competency Framework for Teachers','url','https://www.unesco.org/en/articles/ai-competency-framework-teachers','note','Kompetensi pendidik terkait AI dan pedagogi.'),
  jsonb_build_object('title','Panduan UNESCO tentang GenAI dalam pendidikan','url','https://www.unesco.org/en/articles/guidance-generative-ai-education-and-research','note','Privasi, validasi pedagogis, dan penggunaan AI yang bertanggung jawab.'))
 WHEN 'perencanaan-karier-portofolio-keterampilan' THEN jsonb_build_array(
  jsonb_build_object('title','OECD Learning Compass 2030','url','https://www.oecd.org/en/data/tools/oecd-learning-compass-2030.html','note','Kerangka kompetensi masa depan; bukan standar wajib Indonesia.'),
  jsonb_build_object('title','ESCO','url','https://esco.ec.europa.eu/en/use-esco','note','Taksonomi keterampilan dan pekerjaan untuk referensi lintas negara.'),
  jsonb_build_object('title','O*NET Content License','url','https://www.onetonline.org/help/license','note','Rujukan keterampilan dan pekerjaan; perhatikan atribusi dan lisensi.'))
 ELSE jsonb_build_array(jsonb_build_object('title','Panduan UNESCO tentang GenAI dalam pendidikan','url','https://www.unesco.org/en/articles/guidance-generative-ai-education-and-research','note','Rujukan umum.')) END,
'summary',v.summary,'objectives',jsonb_build_array(v.objective),'sections',jsonb_build_array(jsonb_build_object('heading','Materi inti','body',v.body),jsonb_build_object('heading','Praktik yang disarankan','body',v.practice)),'exercise',v.exercise),v.lesson_position
FROM (VALUES
('literasi-informasi-berpikir-kritis',1,1,'Membuat Pertanyaan Pencarian yang Tajam','Pertanyaan yang spesifik membantu menemukan sumber yang relevan dan mengurangi hasil yang tidak terkait.','Mengubah topik luas menjadi pertanyaan yang dapat dijawab dengan bukti.','Tentukan kebutuhan informasi, kata kunci utama dan sinonim, rentang waktu, jenis sumber, dan batasan geografis. Ulangi pencarian dengan istilah berbeda; simpan tanggal akses dan URL sumber.','Bandingkan hasil dari sumber resmi, penelitian, dan media. Periksa apakah masing-masing benar-benar menjawab pertanyaan.','Buat tiga kueri pencarian berbeda untuk memeriksa klaim tentang suatu keterampilan kerja.'),
('literasi-informasi-berpikir-kritis',1,2,'Mencatat Sumber dan Konteks','Catatan sumber memungkinkan pembaca menelusuri asal klaim dan memahami konteksnya.','Mencatat penulis/lembaga, tanggal, judul, URL, lisensi, dan klaim yang didukung.','Pisahkan kutipan singkat, parafrasa, dan pendapat sendiri. Simpan konteks halaman serta tanggal pengambilan. Jangan menganggap hasil pencarian sebagai bukti penuh; buka sumber asli.','Buat catatan bibliografi untuk dua sumber dan tuliskan satu hal yang belum bisa dipastikan.','Buat kartu sumber berisi judul, lembaga, tanggal, URL, lisensi, ringkasan dan keterbatasan.'),
('literasi-informasi-berpikir-kritis',2,1,'Memeriksa Kredibilitas dan Kepentingan','Kredibilitas bergantung pada keahlian, bukti, transparansi, konteks, dan potensi konflik kepentingan.','Mengevaluasi siapa yang menerbitkan, bukti apa yang diberikan, dan siapa yang diuntungkan.','Periksa otoritas penulis, tanggal, metode, referensi, tujuan publikasi, pendanaan, dan apakah sumber lain yang independen mengonfirmasi klaim. Domain resmi membantu, tetapi tidak membuat setiap klaim otomatis benar.','Gunakan beberapa sumber independen untuk klaim penting. Catat bagian yang bertentangan dan alasan kemungkinan perbedaannya.','Nilai satu halaman web menggunakan kriteria penulis, bukti, tanggal, tujuan, dan konfirmasi independen.'),
('literasi-informasi-berpikir-kritis',2,2,'Membedakan Fakta, Inferensi, dan Opini','Fakta yang terukur, inferensi, opini, dan dugaan memerlukan tingkat keyakinan yang berbeda.','Mengelompokkan pernyataan berdasarkan jenis bukti dan ketidakpastiannya.','Tandai klaim yang dapat diperiksa, interpretasi yang ditarik dari data, penilaian normatif, dan asumsi yang belum diuji. Hindari kesimpulan sebab-akibat hanya dari korelasi.','Tuliskan bukti yang akan mengubah kesimpulan dan cari penjelasan alternatif.','Klasifikasikan lima pernyataan dalam artikel menjadi fakta, inferensi, opini, atau klaim yang belum terverifikasi.'),
('literasi-informasi-berpikir-kritis',3,1,'Menyintesis Banyak Sumber','Sintesis menghubungkan temuan dari sumber yang berbeda, bukan sekadar menumpuk kutipan.','Merangkum kesepakatan, perbedaan, dan batas bukti lintas sumber.','Buat matriks klaim-sumber. Bandingkan metode, waktu, populasi, definisi, dan tingkat bukti. Pertahankan atribusi dan tuliskan jika tidak ada konsensus.','Utamakan parafrasa orisinal dan kutipan seperlunya sesuai lisensi. Jangan menyalin keseluruhan modul berhak cipta.','Tulis ringkasan 150 kata dengan dua sumber yang mendukung dan satu batasan.'),
('literasi-informasi-berpikir-kritis',3,2,'Menulis Kesimpulan dengan Ketidakpastian','Kesimpulan yang dapat dipercaya menyatakan apa yang diketahui, belum diketahui, dan apa langkah berikutnya.','Menyampaikan temuan, tingkat keyakinan, keterbatasan, dan rekomendasi.','Gunakan bahasa yang sebanding dengan bukti: menunjukkan, mengindikasikan, atau belum cukup bukti. Pisahkan fakta dari rekomendasi dan sebutkan tanggal sumber bila informasi mudah berubah.','Minta pembaca lain menelusuri setiap klaim penting ke sumber asal.','Tulis kesimpulan satu paragraf yang memuat temuan, batasan, dan pertanyaan terbuka.'),
('literasi-digital-keamanan-data',1,1,'Jejak Digital dan Data Pribadi','Aktivitas daring dapat meninggalkan data yang bertahan, disalin, atau dibagikan di luar audiens awal.','Mengidentifikasi informasi pribadi dan mengurangi paparan yang tidak diperlukan.','Tinjau informasi profil, izin aplikasi, lokasi, metadata berkas, dan pengaturan berbagi. Terapkan minimisasi data: bagikan hanya yang dibutuhkan untuk tujuan yang jelas.','Untuk data anak atau pembelajar, gunakan persetujuan dan akses sesuai peran; jangan unggah data sensitif ke layanan AI tanpa dasar dan perlindungan yang memadai.','Audit pengaturan privasi sebuah akun dan buat daftar perubahan yang paling berdampak.'),
('literasi-digital-keamanan-data',1,2,'Persetujuan dan Berbagi Berkas','Persetujuan harus spesifik, dipahami, dan sesuai tujuan; tautan publik dapat tersebar lebih jauh dari yang diharapkan.','Memilih izin akses minimum dan memeriksa siapa yang dapat membuka berkas.','Gunakan akses terbatas, masa berlaku tautan bila tersedia, dan pencabutan akses setelah kebutuhan berakhir. Periksa penerima sebelum mengirim data pribadi atau karya orang lain.','Bedakan izin melihat, memberi komentar, dan mengedit. Jangan menggunakan data untuk tujuan baru tanpa peninjauan.','Ubah sebuah dokumen dari akses publik menjadi akses terbatas dan jelaskan alasannya.'),
('literasi-digital-keamanan-data',2,1,'Kata Sandi, MFA, dan Pemulihan Akun','Kata sandi unik dan autentikasi multifaktor mengurangi risiko pengambilalihan akun.','Menerapkan pengelolaan kredensial dan pemulihan akun yang aman.','Gunakan pengelola kata sandi tepercaya, kata sandi unik, MFA bila tersedia, dan kode pemulihan yang disimpan aman. Jangan pernah mengirim kata sandi atau kode OTP ke orang lain.','Periksa sesi aktif, perangkat yang dikenal, dan metode pemulihan; tutup sesi yang tidak dikenali.','Buat checklist pengamanan akun tanpa menuliskan kata sandi aktual.'),
('literasi-digital-keamanan-data',2,2,'Mengenali Phishing dan Rekayasa Sosial','Serangan sering memanfaatkan urgensi, otoritas palsu, rasa takut, atau imbalan yang terlalu bagus.','Memeriksa pengirim, domain, tautan, lampiran, dan permintaan informasi rahasia.','Jangan klik tautan dari pesan tak terduga. Buka layanan melalui alamat resmi yang diketik sendiri, verifikasi permintaan melalui kanal kedua, dan laporkan pesan mencurigakan.','Jangan mengunduh lampiran yang tidak diharapkan atau memasukkan kredensial setelah mengikuti tautan dari pesan.','Identifikasi tanda bahaya pada contoh email simulasi dan jelaskan cara melaporkannya.'),
('literasi-digital-keamanan-data',3,1,'Kolaborasi Digital yang Inklusif','Kolaborasi digital efektif memerlukan tujuan, norma komunikasi, aksesibilitas, dan pencatatan keputusan.','Memilih kanal, format, dan aturan kolaborasi sesuai kebutuhan tim.','Gunakan judul deskriptif, struktur yang jelas, teks alternatif untuk gambar penting, dan catatan keputusan. Sesuaikan jam komunikasi dan jangan menganggap semua anggota selalu tersedia.','Pastikan dokumen dapat diakses dengan keyboard dan pembaca layar jika relevan.','Buat panduan kerja tim satu halaman yang mencakup kanal, respons, keputusan, dan aksesibilitas.'),
('literasi-digital-keamanan-data',3,2,'Memeriksa Informasi dan Media Sintetis','Konten digital dapat dimanipulasi atau dihasilkan AI; tampilan meyakinkan bukan bukti keaslian.','Menggunakan pemeriksaan silang dan konteks sebelum membagikan konten.','Periksa sumber asli, tanggal, konteks, metadata bila relevan, dan peliputan independen. Pencarian gambar balik dapat membantu, tetapi tidak selalu menentukan keaslian.','Jangan menyebarkan konten yang belum terverifikasi atau mengungkap identitas orang berdasarkan dugaan.','Pilih sebuah klaim viral hipotetis dan susun prosedur verifikasi bertahap.'),
('kecerdasan-buatan-dasar-etika-praktik',1,1,'Apa yang Bisa dan Tidak Bisa Dilakukan AI','Sistem AI mempelajari pola dari data dan dapat menghasilkan jawaban yang masuk akal tetapi salah.','Menjelaskan kemampuan, batasan, bias, dan kebutuhan verifikasi AI generatif.','Model bahasa memprediksi keluaran berdasarkan pola; ia tidak menjamin kebenaran, kelengkapan, atau pemahaman konteks. Hasil dipengaruhi prompt, data, desain sistem, dan batas pengetahuan.','Untuk keputusan berisiko tinggi, gunakan sumber primer dan peninjauan manusia. Jangan menganggap keyakinan bahasa sebagai ukuran akurasi.','Tandai klaim yang perlu diverifikasi pada jawaban AI contoh dan tentukan sumber pembanding.'),
('kecerdasan-buatan-dasar-etika-praktik',1,2,'Bias, Data, dan Dampak AI','AI dapat mencerminkan ketimpangan dalam data, tujuan optimasi, dan konteks penggunaan.','Mengidentifikasi siapa yang mungkin dirugikan dan cara menguji hasil secara adil.','Periksa representasi kelompok, kualitas data, definisi keberhasilan, aksesibilitas, dan dampak kesalahan. Tidak ada satu metrik yang membuktikan keadilan pada semua konteks.','Libatkan pihak yang terdampak, dokumentasikan keterbatasan, dan sediakan jalur banding manusia.','Buat daftar pertanyaan audit sebelum menggunakan alat AI untuk menilai pekerjaan pembelajar.'),
('kecerdasan-buatan-dasar-etika-praktik',2,1,'Merancang Prompt yang Dapat Dievaluasi','Prompt yang jelas menyebut tujuan, konteks, audiens, batasan, dan format hasil yang diharapkan.','Menyusun prompt terstruktur dan menentukan kriteria mutu keluaran.','Nyatakan tugas, konteks non-sensitif, batasan, format, dan kriteria keberhasilan. Minta AI menyatakan asumsi dan pertanyaan klarifikasi; tetap periksa hasilnya.','Hindari memasukkan data rahasia. Prompt tidak mengubah keluaran AI menjadi sumber otoritatif.','Perbaiki prompt yang ambigu lalu bandingkan hasilnya menggunakan rubrik sederhana.'),
('kecerdasan-buatan-dasar-etika-praktik',2,2,'Verifikasi Fakta dan Kutipan AI','Kutipan, angka, sumber, dan referensi yang dihasilkan AI dapat keliru atau tidak ada.','Memverifikasi setiap klaim penting melalui sumber asli.','Buka sumber yang disebut, periksa bagian yang mendukung klaim, tanggal dan konteks. Jika sumber tidak dapat ditemukan atau tidak mendukung klaim, hapus atau nyatakan belum terverifikasi.','Jangan mengarang sitasi. Catat sumber yang benar-benar dibaca dan jelaskan penggunaan AI sesuai aturan institusi.','Verifikasi tiga referensi dari contoh jawaban dan tandai statusnya: benar, sebagian, atau tidak ditemukan.'),
('kecerdasan-buatan-dasar-etika-praktik',3,1,'Privasi, Hak Cipta, dan Penggunaan AI','Penggunaan AI perlu memperhatikan data pribadi, lisensi, atribusi, dan aturan lembaga.','Memilih data dan materi yang boleh digunakan serta menjelaskan kontribusi AI.','Gunakan sumber berlisensi atau yang izin penggunaannya jelas. Buat ringkasan orisinal, atribusikan sumber, dan jangan mengunggah karya orang lain secara massal tanpa izin.','Untuk pembelajaran, jelaskan kapan AI digunakan dan bagian mana yang diverifikasi manusia. Ikuti kebijakan institusi dan usia pengguna.','Buat deklarasi penggunaan AI yang jujur untuk tugas belajar.'),
('kecerdasan-buatan-dasar-etika-praktik',3,2,'Merancang Proses Human-in-the-Loop','Manusia tetap bertanggung jawab pada keputusan yang berdampak terhadap hak, kesempatan, atau keselamatan seseorang.','Menentukan titik verifikasi manusia dan jalur koreksi.','Batasi hak agen, gunakan data minimum, simpan jejak audit yang sesuai, uji kegagalan, dan minta persetujuan sebelum tindakan yang berdampak. Berikan cara untuk mengoreksi hasil atau mengajukan banding.','Jangan menggunakan AI untuk mendiagnosis kesehatan mental atau menyimpulkan kepribadian dari perilaku tanpa dasar dan tata kelola yang sah.','Gambarkan alur AI memberi saran, manusia meninjau, dan pembelajar dapat mengoreksi.'),
('perencanaan-karier-portofolio-keterampilan',1,1,'Mengubah Aspirasi Menjadi Target Keterampilan','Target belajar yang terukur menghubungkan aspirasi dengan tindakan dan bukti yang dapat diamati.','Memecah aspirasi karier menjadi keterampilan dan sasaran yang dapat dinilai.','Gunakan target spesifik, ukuran keberhasilan, tenggat, dan bukti. Mulai dari pekerjaan atau proyek yang diminati, lalu petakan keterampilan yang dibutuhkan tanpa menganggap satu pekerjaan hanya memerlukan satu profil.','Pilih satu target yang realistis untuk 2–4 minggu dan satu cara meminta umpan balik.','Tuliskan target keterampilan dengan hasil yang dapat diamati dan bukti penyelesaiannya.'),
('perencanaan-karier-portofolio-keterampilan',1,2,'Membaca Peta Keterampilan dan Pekerjaan','Taksonomi pekerjaan dan keterampilan membantu eksplorasi, tetapi tidak menjamin pekerjaan atau pendapatan.','Menggunakan kerangka keterampilan untuk menemukan kebutuhan belajar dan opsi karier.','Bandingkan beberapa sumber seperti O*NET dan ESCO; perhatikan negara, bahasa, tanggal, dan definisi. Cocokkan dengan iklan kerja lokal terkini dan wawancara informasional bila memungkinkan.','Hindari menganggap klasifikasi luar negeri sebagai standar wajib Indonesia. Sesuaikan dengan sektor dan konteks lokal.','Pilih satu peran kerja dan petakan lima keterampilan beserta sumber yang mendukungnya.'),
('perencanaan-karier-portofolio-keterampilan',2,1,'Bukti Kerja yang Dapat Ditelusuri','Portofolio kuat menunjukkan proses, kontribusi pribadi, hasil, dan refleksi, bukan hanya klaim kemampuan.','Menyusun bukti yang relevan, dapat diverifikasi, dan aman dibagikan.','Gunakan artefak yang boleh dibagikan, jelaskan konteks dan peran Anda, serta hilangkan data rahasia. Sertakan umpan balik atau hasil yang dapat diperiksa jika diizinkan.','Jangan mengunggah data pelanggan, rekan kerja, atau organisasi tanpa izin. Pisahkan bukti publik dan privat.','Buat deskripsi satu artefak portofolio: tujuan, kontribusi, hasil, bukti, dan hal yang dipelajari.'),
('perencanaan-karier-portofolio-keterampilan',2,2,'Menulis Refleksi Berbasis Bukti','Refleksi mengubah pengalaman menjadi rencana perbaikan yang spesifik.','Menghubungkan tindakan, hasil, umpan balik, dan langkah berikutnya.','Gunakan urutan situasi, tindakan, hasil, pembelajaran, dan rencana berikutnya. Bedakan hasil yang dapat diatribusikan kepada Anda dari faktor eksternal.','Gunakan umpan balik sebagai bukti untuk mengembangkan keterampilan, bukan sebagai label permanen tentang pribadi.','Tulis refleksi 150 kata dari sebuah proyek dan tetapkan satu eksperimen perbaikan.'),
('perencanaan-karier-portofolio-keterampilan',3,1,'Membuat Rencana Belajar 90 Hari','Rencana efektif membagi tujuan besar menjadi siklus belajar, praktik, umpan balik, dan tinjauan.','Menyusun jadwal, hasil kerja, dan titik pemeriksaan yang realistis.','Pilih maksimal dua prioritas, jadwalkan sesi belajar dan praktik, tentukan bukti, serta rencanakan umpan balik. Tinjau kemajuan tiap dua minggu dan ubah rencana bila kondisi berubah.','Sediakan waktu untuk istirahat, tanggung jawab lain, dan akses belajar yang berbeda.','Susun rencana empat minggu pertama dengan satu artefak atau demonstrasi per minggu.'),
('perencanaan-karier-portofolio-keterampilan',3,2,'Meninjau Kemajuan dan Menyesuaikan Rencana','Kemajuan lebih baik dinilai dari bukti tugas yang relevan dan konsisten daripada satu skor tunggal.','Menggunakan rubrik, umpan balik, dan refleksi untuk menentukan langkah berikutnya.','Bandingkan hasil dengan kriteria yang diketahui, simpan versi bukti, minta umpan balik spesifik, dan catat konteks. Jika bukti belum cukup, rencanakan praktik tambahan sebelum menyimpulkan penguasaan.','Hindari klaim sertifikasi atau tingkat kompetensi tanpa rubrik yang transparan dan verifikasi yang sesuai.','Tinjau satu target: bukti apa yang tersedia, apa yang belum, dan apa langkah berikutnya.')
) AS v(course_slug,module_position,lesson_position,title,summary,objective,body,practice,exercise)
JOIN public.courses c ON c.slug=v.course_slug
JOIN public.modules m ON m.course_id=c.id AND m.position=v.module_position
ON CONFLICT (module_id,position) DO UPDATE SET title=EXCLUDED.title,content=EXCLUDED.content;

COMMIT;
